corrected_code:
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, '/var/data/dicom_uploads/'),
  filename: (req, file, cb) => cb(null, `${req.params.patientId}_${Date.now()}.dcm`)
});
const upload = multer({ storage });

app.post('/clinic/patients/:patientId/scans', verifyDoctorJwt, async (req, res, next) => {
  const isPatientAssigned = await db.query(
    'SELECT id FROM clinic_assignments WHERE patient_id = $1 AND doctor_id = $2',
    [req.params.patientId, req.user.doctorId]
  );
  if (isPatientAssigned.rowCount === 0) {
    return res.status(403).json({ error: 'Patient not assigned to this physician' });
  }
  next();
}, upload.array('scans', 5), async (req, res) => {
  const { patientId } = req.params;
  const savedFiles = req.files.map(f => f.path);

  await db.query(
    'INSERT INTO patient_imaging (patient_id, file_paths, uploaded_at) VALUES ($1, $2, NOW())',
    [patientId, savedFiles]
  );

  res.json({ status: 'scans_attached', patientId, count: savedFiles.length });
});
